code.source:
#include <stdio.h>

int main(void)
{
    int age;            // declare: make a box called age
    age = 19;           // assign: put 19 in the box

    int rollNo = 42;    // declare and assign together
    int marks = 78;

    printf("Age: %d\n", age);
    printf("Roll no: %d\n", rollNo);

    marks = marks + 5;  // bonus marks
    printf("Marks after bonus: %d\n", marks);

    return 0;
}

